function aurumEuro(request, url, path) {
  const cors = { "Access-Control-Allow-Origin": "*" };
  if (path === "/aurum-euro" || path === "/aurum-euro/") return new Response(AURUM_HTML, { headers: { "Content-Type": "text/html; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/stocks" || path === "/aurum-euro/stocks/") return new Response(AURUM_STOCKS, { headers: { "Content-Type": "text/html; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/snapshot.json") return new Response(JSON.stringify(AURUM_SNAP), { headers: { "Content-Type": "application/json; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/static/styles.css") return new Response(AURUM_CSS, { headers: { "Content-Type": "text/css; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/static/app.js") return new Response(AURUM_JS, { headers: { "Content-Type": "application/javascript; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/static/methodology.html") return new Response(AURUM_METH, { headers: { "Content-Type": "text/html; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/static/provenance.html") return new Response(AURUM_PROV, { headers: { "Content-Type": "text/html; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/static/sources.html") return new Response(AURUM_SOURCES, { headers: { "Content-Type": "text/html; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/api/v1/definition") return Response.json(AURUM_SNAP.definition, { headers: cors });
  if (path === "/aurum-euro/api/v1/health" || path === "/aurum-euro/api/v1/status")
    return Response.json({ status:"ok", service:"aurum-euro", publication_unit:"€Au", ...AURUM_SNAP.status, venues:AURUM_VENUES.n }, { headers: cors });
  if (path === "/aurum-euro/api/v1/gold") return Response.json({ unit:"EUR per troy ounce of gold (input to €Au)", rows:AURUM_SNAP.gold }, { headers: cors });
  if (path === "/aurum-euro/api/v1/datasets" || path === "/aurum-euro/api/v1/catalog")
    return Response.json({ publication_unit:"€Au", datasets:AURUM_SNAP.datasets, series:AURUM_SNAP.series, catalog:AURUM_SNAP.catalog }, { headers: cors });
  if (path === "/aurum-euro/api/v1/stocks/venues") return Response.json(AURUM_VENUES, { headers: cors });
  return new Response(JSON.stringify({ error:"Not found", path }), { status:404, headers: { "Content-Type":"application/json", ...cors } });
}

